    if hasattr(dep, 'name') and hasattr(dep, 'version'):
        # Handle dparse dependency objects
        name = dep.name
        version = dep.version
        if version:
            req = f"{name}=={version}"
        else:
            req = name
    else:
        # Handle string requirements
        req = str(dep)

    return SafetyRequirement(req)

def read_requirements(fh: Any, resolve: bool=True) ->Generator[Package,
    None, None]:
